const CHOCO_DRILL_MATERIALS=['待機','鉄','銅','銀','金','ダイヤ'];
const chocoDrillLevel=(drill,lucky)=>Math.min(5,drill.hits.length+lucky.hits.filter(n=>lucky.numbers.slice(0,2).includes(n)).length);
