  const neighbor=chocoRandom(w)<.5?row[c-1]:above?.[c],color=chocoRandom(w)<.52&&neighbor?.color>=0?neighbor.color:Math.floor(chocoRandom(w)*4),p=chocoRandom(w);let kind=null,sum=0;
