  if(CHOCO_ORES[kind]){const def=CHOCO_ORES[kind],baseValue=def.min+Math.floor(chocoRandom(w)*((def.max-def.min)/def.step+1))*def.step;Object.assign(tile,{item:'ore',ore:kind,baseValue,value:baseValue,multiplier:1});}
